const body = $input.item.json.body || $input.item.json;
const booking = body.booking || body;
const customer = booking.customer || {};

const tourName = booking.tourName || 'Tour Costa Rica';
const dateStr = booking.date || new Date().toISOString().slice(0, 10);
const timeStr = booking.time || '08:00 AM';
const bookingId = booking.bookingId || 'CR-TOUR';
const pickup = booking.pickupHotel || 'Por confirmar en destino';
const pax = (parseInt(booking.adults || 1, 10) + parseInt(booking.children || 0, 10));
const customerName = customer.name || 'Viajero';
const customerPhone = customer.phone || 'Sin teléfono';

// Construir timestamp de inicio y fin estimado (3.5 horas por defecto)
let startDateTime = `${dateStr}T08:00:00-06:00`;
let endDateTime = `${dateStr}T11:30:00-06:00`;

if (timeStr.toLowerCase().includes('pm')) {
  const num = parseInt(timeStr, 10) || 1;
  const h24 = num === 12 ? 12 : num + 12;
  const padH = String(h24).padStart(2, '0');
  startDateTime = `${dateStr}T${padH}:00:00-06:00`;
  endDateTime = `${dateStr}T${String(h24 + 3).padStart(2, '0')}:30:00-06:00`;
} else if (timeStr.toLowerCase().includes('am')) {
  const num = parseInt(timeStr, 10) || 8;
  const padH = String(num).padStart(2, '0');
  startDateTime = `${dateStr}T${padH}:00:00-06:00`;
  endDateTime = `${dateStr}T${String(num + 3).padStart(2, '0')}:30:00-06:00`;
}

const summary = `🌴 [${bookingId}] ${tourName} - ${pax} pax (${customerName})`;
const description = `🌿 DETALLES DE OPERACIÓN - COSTA RICA TOURS\n\n• Reserva: ${bookingId}\n• Tour: ${tourName}\n• Pasajeros: ${pax} (${booking.adults || 1} adultos, ${booking.children || 0} niños)\n• Cliente: ${customerName}\n• Teléfono: ${customerPhone}\n• Hotel Recogida: ${pickup}\n• Total: $${booking.totalUSD || 0} USD\n• Estado: Confirmado / Pago Acreditado\n\n¡Pura Vida!`;

return {
  bookingId: bookingId,
  summary: summary,
  description: description,
  location: pickup,
  start: { dateTime: startDateTime, timeZone: 'America/Costa_Rica' },
  end: { dateTime: endDateTime, timeZone: 'America/Costa_Rica' }
};
